#define LUA_UNLIKELY(x) __builtin_expect(!!(x), 0)

typedef enum {
    VAL_NIL,
    VAL_BOOL,
    VAL_NUMBER,
    VAL_STRING,
    VAL_TABLE,
    VAL_BUFFER,
    VAL_THREAD,
    VAL_FUNC,
    VAL_FILE,
    VAL_CLOSURE,
} lua_ValType;

typedef struct {
    lua_ValType type;
    uint8_t number_kind; /* 1=integer, 2=float; only when type==VAL_NUMBER */
    union {
        bool bval;
        double nval;
        int64_t ival;   /* exact integer when number_kind == 1 */
        const char* sval;
        void* tval;
        void* fval; // Cast to function pointer when needed
    } as;
} lua_Value;

typedef struct {
    FILE* f;
    bool is_pipe;
    bool is_stdio;
} lua_File;

typedef struct {
    uint32_t hash;
    size_t len;
    char data[];
} lua_String;

#define LUA_TABLE_INLINE_CAP 4

typedef struct {
    lua_Value* array;
    int array_size;
    int array_capacity;
    lua_Value inline_array[LUA_TABLE_INLINE_CAP];
    bool array_inline;
    /* Robin-Hood hash part: struct-of-arrays for cache-efficient probing */
    lua_Value* hash_keys;
    lua_Value* hash_vals;
    int capacity;
    int count;
    /* Small-table optimization: embed inline storage for up to LUA_TABLE_INLINE_CAP entries */
    lua_Value inline_keys[LUA_TABLE_INLINE_CAP];
    lua_Value inline_vals[LUA_TABLE_INLINE_CAP];
    bool hash_inline;
    /* Last-access cache: avoids re-hashing on repeated access to the same key */
    lua_Value last_key;
    int last_idx;
    lua_Value metatable;
    bool frozen;
} lua_Table;

