static inline uint32_t lua_hash_value(lua_Value v) {
    switch (v.type) {
        case VAL_NUMBER: {
            union { double d; uint64_t u; } u;
            u.d = lua_num(v);
            uint64_t x = u.u;
            x ^= x >> 33;
            x *= 0xff51afd7ed558ccdULL;
            x ^= x >> 33;
            x *= 0xc4ceb9fe1a85ec53ULL;
            x ^= x >> 33;
            return (uint32_t)x;
        }
        case VAL_STRING: {
            lua_String* s = (lua_String*)((char*)v.as.sval - offsetof(lua_String, data));
            return s->hash;
        }
    case VAL_BOOL: return v.as.bval ? 1 : 0;
    default: {
        uintptr_t p = (uintptr_t)v.as.tval;
        #if UINTPTR_MAX == UINT32_MAX
            return (uint32_t)(p ^ (p >> 16));
        #else
            return (uint32_t)(p ^ (p >> 32));
        #endif
    }
    }
}

static inline uint32_t lua_hash_num(double n) {
    union { double d; uint64_t u; } u;
    u.d = n;
    uint64_t x = u.u;
    x ^= x >> 33;
    x *= 0xff51afd7ed558ccdULL;
    x ^= x >> 33;
    x *= 0xc4ceb9fe1a85ec53ULL;
    x ^= x >> 33;
    return (uint32_t)x;
}

static inline uint32_t lua_hash_i64(int64_t n) {
    return lua_hash_num((double)n);
}

