static inline const char* lua_str_sub_cstr(const char* str, int64_t start, int64_t end) {
    if (!str) str = "";
    int64_t len = (int64_t)strlen(str);
    if (start < 0) start = len + start + 1;
    if (end < 0) end = len + end + 1;
    if (start < 1) start = 1;
    if (end > len) end = len;
    if (start > end || start > len || end < 1) {
        lua_Value out = lua_val_from_str_len("", 0);
        return lua_to_str(out);
    }
    int64_t sublen = end - start + 1;
    lua_Value out = lua_val_from_str_len(str + start - 1, (size_t)sublen);
    return lua_to_str(out);
}

static inline lua_Value lua_str_byte(lua_Value s, lua_Value i_val, lua_Value j_val) {
    (void)j_val;
    const char* str = lua_to_str(s);
    int len = (int)lua_str_byte_len(s);
    int idx = i_val.type == VAL_NIL ? 1 : (int)lua_to_num(i_val);
    if (idx < 0) idx = len + idx + 1;
    if (idx < 1 || idx > len) return lua_val_nil();
    return lua_val_from_num((double)(unsigned char)str[idx - 1]);
}

static inline int64_t lua_str_byte_i64(lua_Value s, lua_Value i_val, lua_Value j_val) {
    (void)j_val;
    const char* str = lua_to_str(s);
    int len = (int)lua_str_byte_len(s);
    int idx = i_val.type == VAL_NIL ? 1 : (int)lua_to_num(i_val);
    if (idx < 0) idx = len + idx + 1;
    if (idx < 1 || idx > len) return 0;
    return (int64_t)(unsigned char)str[idx - 1];
}

static int duo_lp_has_magic(const char* pat) {
    for (const char* p = pat; *p; p++) {
        if (*p == '^' || *p == '$' || *p == '.' || *p == '(' || *p == ')' ||
            *p == '%' || *p == '+' || *p == '-' || *p == '?' || *p == '*' || *p == '[') {
            return 1;
        }
    }
    return 0;
}

static int duo_lp_class_test(int c, const char** pp, const char* end) {
    const char* p = *pp;
    if (*p != '[') return 0;
    p++;
    int invert = 0;
    if (p < end && *p == '^') { invert = 1; p++; }
    if (p < end && *p == ']') {
        if (c == ']') { p++; while (p < end && *p != ']') p++; if (p < end) p++; *pp = p; return invert ? 0 : 1; }
        p++;
    }
    int found = 0;
    while (p < end && *p != ']') {
        if (*p == '%' && p + 1 < end) {
            p++;
            char spec = *p++;
            int m = 0;
            if (spec == 'a') m = isalpha(c);
            else if (spec == 'c') m = iscntrl(c);
            else if (spec == 'd') m = isdigit(c);
            else if (spec == 'l') m = islower(c);
            else if (spec == 'p') m = ispunct(c);
            else if (spec == 's') m = isspace(c);
            else if (spec == 'u') m = isupper(c);
            else if (spec == 'w') m = isalnum(c) || c == '_';
            else if (spec == 'x') m = isxdigit(c);
            else if (spec == 'z') m = c == 0;
            else m = (c == spec);
            if (m) found = 1;
        } else if (p + 2 < end && p[1] == '-') {
            char lo = *p; p += 2; char hi = *p++;
            if (lo <= c && c <= hi) found = 1;
        } else {
            if (c == *p) found = 1;
            p++;
        }
    }
    if (p < end && *p == ']') p++;
    *pp = p;
    return invert ? !found : found;
}

static int duo_lp_item_match(int c, const char** pp, const char* end) {
    const char* p = *pp;
    if (p >= end) return 0;
    if (*p == '.') { (*pp) = p + 1; return c != '\0'; }
    if (*p == '[') return duo_lp_class_test(c, pp, end);
    if (*p == '%' && p + 1 < end) {
        p++;
        char spec = *p++;
        int m = 0;
        if (spec == 'a') m = isalpha(c);
        else if (spec == 'c') m = iscntrl(c);
        else if (spec == 'd') m = isdigit(c);
        else if (spec == 'l') m = islower(c);
        else if (spec == 'p') m = ispunct(c);
        else if (spec == 's') m = isspace(c);
        else if (spec == 'u') m = isupper(c);
        else if (spec == 'w') m = isalnum(c) || c == '_';
        else if (spec == 'x') m = isxdigit(c);
        else if (spec == 'z') m = c == 0;
        else m = (c == spec);
        *pp = p;
        return m;
    }
    char lit = *p;
    (*pp) = p + 1;
    return c == lit;
}

#define DUO_LP_MAXCAP 32

/* Skip one pattern item (no quantifier). Returns pointer past the item. */
static const char* duo_lp_skip_item(const char* p, const char* end) {
    if (p >= end) return end;
    if (*p == '.') return p + 1;
    if (*p == '[') {
        const char* q = p + 1;
        if (q < end && *q == '^') q++;
        if (q < end && *q == ']') q++;
        while (q < end && *q != ']') {
            if (*q == '%' && q + 1 < end) q += 2;
            else q++;
        }
        if (q < end && *q == ']') q++;
        return q;
    }
    if (*p == '%' && p + 1 < end) {
        if (p[1] == 'b') return (p + 4 <= end) ? p + 4 : end;
        return p + 2;
    }
    if (*p == '(') {
        const char* q = p + 1;
        int depth = 1;
        while (q < end && depth > 0) {
            if (*q == '(') depth++;
            else if (*q == ')') depth--;
            q++;
        }
        return q;
    }
    return p + 1;
}

/* Match one occurrence of item [p, item_end) at subject offset si.
   Returns 1 on match and sets *consumed (may be >1 for %bXY). */
static int duo_lp_item_at(const char* s, size_t slen, size_t si,
                          const char* p, const char* end, size_t* consumed) {
    if (si >= slen) return 0;
    if (p >= end) return 0;
    int c = (unsigned char)s[si];
    if (*p == '.') { *consumed = 1; return c != 0; }
    if (*p == '[') {
        const char* pp = p;
        int m = duo_lp_class_test(c, &pp, end);
        *consumed = 1;
        return m;
    }
    if (*p == '%' && p + 1 < end && p[1] == 'b') {
        if (p + 3 >= end) return 0;
        char open = p[2], close = p[3];
        if (c != open) return 0;
        int depth = 1;
        size_t j = si + 1;
        while (j < slen && depth > 0) {
            if (s[j] == open) depth++;
            else if (s[j] == close) depth--;
            j++;
        }
        if (depth != 0) return 0;
        *consumed = j - si;
        return 1;
    }
    {
        const char* pp = p;
        int m = duo_lp_item_match(c, &pp, end);
        *consumed = 1;
        return m;
    }
}

/* Backtracking matcher with capture recording. Matches pattern [p, end)
   starting at subject offset si. Returns final offset or (size_t)-1.
   Capture spans appended to cap_s/cap_e; *ncap tracks the count. */
static size_t duo_lp_match_rec(const char* s, size_t slen, size_t si,
                               const char* p, const char* end,
                               size_t* cap_s, size_t* cap_e, int* ncap) {
    if (p >= end) return si;
    if (*p == '$' && p + 1 == end) return (si == slen) ? si : (size_t)-1;
    if (*p == ')') return (size_t)-1;
    if (*p == '(') {
        const char* close = p + 1;
        int depth = 1;
        while (close < end) {
            if (*close == '(') depth++;
            else if (*close == ')') { depth--; if (depth == 0) break; }
            close++;
        }
        if (close >= end) return (size_t)-1;
        const char* after = close + 1;
        char op = (after < end) ? *after : '\\0';
        if (op == '*' || op == '+' || op == '-' || op == '?') {
            /* quantified capture group: the group records its LAST iteration */
            const char* rest = after + 1;
            size_t maxn = 0;
            size_t* poss = malloc((slen - si + 1) * sizeof(size_t));
            if (!poss) return (size_t)-1;
            poss[0] = si;
            size_t cur = si;
            while (cur < slen) {
                int save = *ncap;
                size_t r = duo_lp_match_rec(s, slen, cur, p + 1, close, cap_s, cap_e, ncap);
                if (r == (size_t)-1 || r == cur) { *ncap = save; break; }
                cur = r;
                maxn++;
                poss[maxn] = cur;
            }
            size_t minn = (op == '+') ? 1 : 0;
            size_t maxc = (op == '?') ? (maxn > 0 ? 1 : 0) : maxn;
            if (maxc < minn) { free(poss); return (size_t)-1; }
            size_t res = (size_t)-1;
            size_t slot = (size_t)*ncap;
            if (op == '-') {
                for (size_t n = minn; n <= maxc; n++) {
                    int save = *ncap;
                    cap_s[slot] = poss[0];
                    cap_e[slot] = poss[n];
                    *ncap = (int)slot + 1;
                    size_t r = duo_lp_match_rec(s, slen, poss[n], rest, end, cap_s, cap_e, ncap);
                    if (r != (size_t)-1) { res = r; break; }
                    *ncap = save;
                }
            } else {
                size_t n = maxc;
                while (1) {
                    int save = *ncap;
                    cap_s[slot] = poss[0];
                    cap_e[slot] = poss[n];
                    *ncap = (int)slot + 1;
                    size_t r = duo_lp_match_rec(s, slen, poss[n], rest, end, cap_s, cap_e, ncap);
                    if (r != (size_t)-1) { res = r; break; }
                    *ncap = save;
                    if (n == minn) break;
                    n--;
                }
            }
            free(poss);
            return res;
        }
        cap_s[*ncap] = si;
        size_t r = duo_lp_match_rec(s, slen, si, p + 1, close, cap_s, cap_e, ncap);
        if (r == (size_t)-1) return (size_t)-1;
        cap_e[*ncap] = r;
        (*ncap)++;
        return duo_lp_match_rec(s, slen, r, after, end, cap_s, cap_e, ncap);
    }
    {
        const char* item_end = duo_lp_skip_item(p, end);
        if (item_end == p) return (size_t)-1;
        char op = (item_end < end) ? *item_end : '\\0';
        if (op == '*' || op == '+' || op == '-' || op == '?') {
            const char* rest = item_end + 1;
            size_t maxn = 0;
            size_t* poss = malloc((slen - si + 1) * sizeof(size_t));
            if (!poss) return (size_t)-1;
            poss[0] = si;
            size_t cur = si;
            while (cur < slen) {
                size_t consumed;
                if (!duo_lp_item_at(s, slen, cur, p, item_end, &consumed)) break;
                cur += consumed;
                maxn++;
                poss[maxn] = cur;
            }
            size_t minn = (op == '+') ? 1 : 0;
            size_t maxc = (op == '?') ? (maxn > 0 ? 1 : 0) : maxn;
            if (maxc < minn) { free(poss); return (size_t)-1; }
            size_t res = (size_t)-1;
            if (op == '-') {
                for (size_t n = minn; n <= maxc; n++) {
                    int save = *ncap;
                    size_t r = duo_lp_match_rec(s, slen, poss[n], rest, end, cap_s, cap_e, ncap);
                    if (r != (size_t)-1) { res = r; break; }
                    *ncap = save;
                }
            } else {
                size_t n = maxc;
                while (1) {
                    int save = *ncap;
                    size_t r = duo_lp_match_rec(s, slen, poss[n], rest, end, cap_s, cap_e, ncap);
                    if (r != (size_t)-1) { res = r; break; }
                    *ncap = save;
                    if (n == minn) break;
                    n--;
                }
            }
            free(poss);
            return res;
        }
        if (si >= slen) return (size_t)-1;
        size_t consumed;
        if (!duo_lp_item_at(s, slen, si, p, item_end, &consumed)) return (size_t)-1;
        return duo_lp_match_rec(s, slen, si + consumed, item_end, end, cap_s, cap_e, ncap);
    }
}

/* Try to match pattern at/after start. Returns 1 with match span + captures. */
static int duo_lp_match_caps(const char* s, size_t slen, size_t start,
                             const char* pat, const char* pat_end,
                             size_t* ms, size_t* me,
                             size_t* cap_s, size_t* cap_e, int* ncap) {
    int anchored = 0;
    if (pat < pat_end && *pat == '^') { anchored = 1; pat++; }
    if (anchored) {
        if (start != 0) return 0;
        *ncap = 0;
        size_t r = duo_lp_match_rec(s, slen, 0, pat, pat_end, cap_s, cap_e, ncap);
        if (r == (size_t)-1) return 0;
        *ms = 0; *me = r;
        return 1;
    }
    for (size_t i = start; i <= slen; i++) {
        *ncap = 0;
        size_t r = duo_lp_match_rec(s, slen, i, pat, pat_end, cap_s, cap_e, ncap);
        if (r != (size_t)-1) { *ms = i; *me = r; return 1; }
    }
    return 0;
}

static int duo_lp_find_at(const char* s, size_t slen, const char* pat, size_t start, size_t* ms, size_t* me) {
    size_t plen = strlen(pat);
    const char* pat_end = pat + plen;
    if (!duo_lp_has_magic(pat)) {
        if (start >= slen) return 0;
        const char* found = strstr(s + start, pat);
        if (!found) return 0;
        *ms = (size_t)(found - s);
        *me = *ms + plen;
        return 1;
    }
    size_t cap_s[DUO_LP_MAXCAP], cap_e[DUO_LP_MAXCAP];
    int ncap = 0;
    return duo_lp_match_caps(s, slen, start, pat, pat_end, ms, me, cap_s, cap_e, &ncap);
}

static inline lua_Value lua_str_find(lua_Value s, lua_Value pat_val, lua_Value init_val, lua_Value plain_val) {
    const char* str = lua_to_str(s);
    const char* pat = lua_to_str(pat_val);
    size_t slen = lua_str_byte_len(s);
    size_t start = 0;
    if (init_val.type != VAL_NIL) start = (size_t)lua_to_num(init_val) > 0 ? (size_t)lua_to_num(init_val) - 1 : 0;
    int plain = 0;
    if (plain_val.type == VAL_BOOL && plain_val.as.bval) plain = 1;
    size_t ms = 0, me = 0;
    if (plain) {
        /* Plain text search */
        size_t plen = strlen(pat);
        if (plen == 0) { if (start <= slen) { lua_mret_clear(); return lua_val_from_num((double)(start + 1)); } return lua_val_nil(); }
        if (start >= slen) return lua_val_nil();
        const char* found = strstr(str + start, pat);
        if (!found) return lua_val_nil();
        lua_mret_clear();
        lua_mret_push(lua_val_from_num((double)((found - str) + (int)plen)));
        return lua_val_from_num((double)((found - str) + 1));
    }
    if (duo_lp_find_at(str, slen, pat, start, &ms, &me)) {
        lua_mret_clear();
        lua_mret_push(lua_val_from_num((double)(me + 1)));
        return lua_val_from_num((double)(ms + 1));
    }
    return lua_val_nil();
}
static inline lua_Value lua_str_find_argv_fn(int argc, lua_Value* argv) {
    lua_Value nil = lua_val_nil();
    return lua_str_find(
        argc > 0 ? argv[0] : nil,
        argc > 1 ? argv[1] : nil,
        argc > 2 ? argv[2] : nil,
        argc > 3 ? argv[3] : nil
    );
}

static inline lua_Value lua_tbl_move(lua_Value a1, lua_Value f_val, lua_Value e_val, lua_Value t_val, lua_Value a2) {
    lua_Value dest = a2.type == VAL_NIL ? a1 : a2;
    int f = (int)lua_to_num(f_val);
    int e = (int)lua_to_num(e_val);
    int t = (int)lua_to_num(t_val);
    if (f > e) return dest;
    int count = e - f + 1;
    
    /* Optimize for array parts */
    if (a1.type == VAL_TABLE && dest.type == VAL_TABLE) {
        lua_Table* t1 = (lua_Table*)a1.as.tval;
        lua_Table* t2 = (lua_Table*)dest.as.tval;
        if (t1 && t2 && f >= 1 && e <= t1->array_size && t >= 1 && (t + count - 1) <= t2->array_size) {
            memmove(&t2->array[t-1], &t1->array[f-1], count * sizeof(lua_Value));
            return dest;
        }
    }

    lua_Value* temp = malloc(count * sizeof(lua_Value));
    for (int i = 0; i < count; i++) {
        temp[i] = lua_table_get_i64(a1, f + i);
    }
    for (int i = 0; i < count; i++) {
        lua_table_set_i64(dest, t + i, temp[i]);
    }
    free(temp);
    return dest;
}

static inline lua_Value lua_tbl_unpack(lua_Value list, lua_Value i_val, lua_Value j_val) {
    int i = i_val.type == VAL_NIL ? 1 : (int)lua_to_num(i_val);
    int j = j_val.type == VAL_NIL ? lua_table_len(list) : (int)lua_to_num(j_val);
    if (j < i) {
        lua_mret_clear();
        return lua_val_nil();
    }
    lua_mret_clear();
    for (int k = i; k <= j && lua_mret_n < LUA_MRET_MAX; k++) {
        lua_mret_push(lua_table_get_i64(list, k));
    }
    return lua_mret_get(0);
}

static jmp_buf error_jmp;
static bool has_error_jmp = false;
static lua_Value last_error;

static inline void lua_error(lua_Value msg) {
    last_error = msg;
    if (has_error_jmp) longjmp(error_jmp, 1);
    fprintf(stderr, "error: %s\n", lua_to_str(msg));
    exit(1);
}

static inline void lua_pcall_store_success(lua_Value r) {
    if (lua_mret_n + 1 < LUA_MRET_MAX) {
        for (int i = lua_mret_n; i > 0; i--) lua_mret_buf[i] = lua_mret_buf[i - 1];
        lua_mret_buf[0] = r;
        lua_mret_n++;
    }
}

static inline bool lua_pcall_bool(lua_Value f, lua_Value arg) {
    jmp_buf old_jmp;
    memcpy(old_jmp, error_jmp, sizeof(jmp_buf));
    bool old_has = has_error_jmp;
    has_error_jmp = true;
    if (setjmp(error_jmp) == 0) {
        lua_Value args[1] = { arg };
        lua_Value r = lua_invoke(f, 1, args);
        has_error_jmp = old_has;
        memcpy(error_jmp, old_jmp, sizeof(jmp_buf));
        lua_pcall_store_success(r);
        return true;
    } else {
        has_error_jmp = old_has;
        memcpy(error_jmp, old_jmp, sizeof(jmp_buf));
        lua_mret_clear();
        lua_mret_push(last_error);
        return false;
    }
}

static inline lua_Value lua_pcall(lua_Value f, lua_Value arg) {
    return lua_val_from_bool(lua_pcall_bool(f, arg));
}

static inline bool lua_pcall_argv_bool(int argc, lua_Value* argv) {
    if (argc < 1) return false;
    jmp_buf old_jmp;
    memcpy(old_jmp, error_jmp, sizeof(jmp_buf));
    bool old_has = has_error_jmp;
    has_error_jmp = true;
    if (setjmp(error_jmp) == 0) {
        lua_Value r = lua_invoke(argv[0], argc - 1, argv + 1);
        has_error_jmp = old_has;
        memcpy(error_jmp, old_jmp, sizeof(jmp_buf));
        lua_pcall_store_success(r);
        return true;
    } else {
        has_error_jmp = old_has;
        memcpy(error_jmp, old_jmp, sizeof(jmp_buf));
        lua_mret_clear();
        lua_mret_push(last_error);
        return false;
    }
}

static inline lua_Value lua_pcall_argv_fn(int argc, lua_Value* argv) {
    return lua_val_from_bool(lua_pcall_argv_bool(argc, argv));
}

static inline lua_Value lua_io_open(lua_Value filename_val, lua_Value mode_val) {
    const char* filename = lua_to_str(filename_val);
    const char* mode = mode_val.type == VAL_NIL ? "r" : lua_to_str(mode_val);
    FILE* f = fopen(filename, mode);
    if (!f) return lua_val_nil();
    lua_File* lf = malloc(sizeof(lua_File));
    lf->f = f;
    lf->is_pipe = false;
    lf->is_stdio = false;
    lua_Value v;
    v.type = VAL_FILE;
    v.as.tval = (void*)lf;
    return v;
}

static inline lua_Value lua_io_close(lua_Value file_val) {
    if (file_val.type == VAL_FILE && file_val.as.tval) {
        lua_File* lf = (lua_File*)file_val.as.tval;
        if (lf->is_stdio) return lua_val_nil();
        if (lf->f) {
            if (lf->is_pipe) {
                pclose(lf->f);
            } else {
                fclose(lf->f);
            }
            lf->f = NULL;
        }
    }
    return lua_val_nil();
}

static inline void lua_close_local(lua_Value v) {
    if (v.type == VAL_NIL) return;
    lua_Value mm = lua_get_metafield_lit(v, "__close", 393739833u, 7);
    if (mm.type == VAL_FUNC || mm.type == VAL_CLOSURE) {
        lua_Value args[2] = { v, lua_val_from_bool(false) };
        (void)lua_invoke(mm, 2, args);
        return;
    }
    if (v.type == VAL_FILE) (void)lua_io_close(v);
}

static inline lua_Value lua_file_write_method(lua_Value file_val, lua_Value s) {
    if (file_val.type == VAL_FILE && file_val.as.tval) {
        lua_File* lf = (lua_File*)file_val.as.tval;
        if (lf->f) {
            lua_write_value(lf->f, s);
        }
    } else if (file_val.type == VAL_BUFFER) {
        lua_str_buf_put(file_val, s);
    }
    return file_val;
}

static inline lua_Value lua_file_read_method(lua_Value file_val, lua_Value fmt_val) {
    if (file_val.type == VAL_FILE && file_val.as.tval) {
        lua_File* lf = (lua_File*)file_val.as.tval;
        if (lf->f) return lua_read_fmt(lf->f, fmt_val);
        return lua_val_nil();
    } else if (file_val.type == VAL_BUFFER) {
        return lua_str_buf_get(file_val);
    }
    return lua_val_nil();
}

static inline lua_Value lua_os_date(lua_Value fmt_val, lua_Value t_val) {
    time_t t = t_val.type == VAL_NIL ? time(NULL) : (time_t)lua_to_num(t_val);
    const char* fmt = fmt_val.type == VAL_NIL ? "%c" : lua_to_str(fmt_val);
    struct tm* ltime = localtime(&t);
    if (!ltime) return lua_val_nil();
    char buf[1024];
    size_t len = strftime(buf, sizeof(buf), fmt, ltime);
    if (len > 0) {
        return lua_val_from_str_len(buf, len);
    }
    return lua_val_nil();
}

static inline lua_Value lua_os_execute(lua_Value cmd_val) {
    if (cmd_val.type == VAL_NIL) {
        return lua_val_from_bool(system(NULL) != 0);
    }
    int res = system(lua_to_str(cmd_val));
    return lua_val_from_bool(res == 0);
}

static inline lua_Value lua_co_running(void) {
    if (active_thread) {
        lua_Value v;
        v.type = VAL_THREAD;
        v.as.tval = active_thread;
        return v;
    }
    return lua_val_nil();
}

static inline lua_Value lua_utf8_len(lua_Value s) {
    const char* str = lua_to_str(s);
    int len = 0;
    while (*str) {
        if ((*str & 0xC0) != 0x80) {
            len++;
        }
        str++;
    }
    return lua_val_from_num((double)len);
}

static inline lua_Value lua_debug_traceback(void) {
    return lua_val_lit("stack traceback:\n  [C]: in function 'debug.traceback'");
}

static inline lua_Value lua_debug_getinfo(lua_Value level, lua_Value opts) {
    (void)level;
    (void)opts;
    lua_Value t = lua_table_new_with_capacity(0, 10);
    lua_table_init_lit(t, "source", lua_val_lit("=[C]"));
    lua_table_init_lit(t, "short_src", lua_val_lit("[C]"));
    lua_table_init_lit(t, "what", lua_val_lit("C"));
    lua_table_init_lit(t, "name", lua_val_lit(""));
    lua_table_init_lit(t, "linedefined", lua_val_from_num(-1));
    lua_table_init_lit(t, "lastlinedefined", lua_val_from_num(-1));
    lua_table_init_lit(t, "currentline", lua_val_from_num(-1));
    lua_table_init_lit(t, "nups", lua_val_from_num(0));
    lua_table_init_lit(t, "nparams", lua_val_from_num(0));
    lua_table_init_lit(t, "isvararg", lua_val_from_bool(false));
    return t;
}

static inline lua_Value lua_select_argv(lua_Value index_val, int argc, lua_Value* argv) {
    if (index_val.type == VAL_STRING && strcmp(index_val.as.sval, "#") == 0) {
        return lua_val_from_num((double)argc);
    }
    int idx = (int)lua_to_num(index_val);
    if (idx < 0) idx = argc + idx + 1;
    if (idx >= 1 && idx <= argc) return argv[idx - 1];
    return lua_val_nil();
}

static inline lua_Value lua_select_v(lua_Value index_val, int argc, ...) {
    lua_Value args[LUA_MRET_MAX];
    if (argc > LUA_MRET_MAX) argc = LUA_MRET_MAX;
    va_list ap;
    va_start(ap, argc);
    for (int i = 0; i < argc; i++) args[i] = va_arg(ap, lua_Value);
    va_end(ap);
    return lua_select_argv(index_val, argc, args);
}

static inline lua_Value lua_math_tointeger(lua_Value v) {
    if (v.type == VAL_NUMBER) {
        double d = lua_num(v);
        if (d == (double)(int64_t)d) {
            return v;
        }
    }
    return lua_val_nil();
}

static inline lua_Value lua_math_modf(lua_Value v) {
    double intpart;
    double frac = modf(lua_to_num(v), &intpart);
    lua_mret_push(lua_val_from_num(frac));
    return lua_val_from_num(intpart);
}

static inline lua_Value lua_math_ult(lua_Value m_val, lua_Value n_val) {
    uint64_t m = (uint64_t)lua_to_num(m_val);
    uint64_t n = (uint64_t)lua_to_num(n_val);
    return lua_val_from_bool(m < n);
}

static inline lua_Value lua_str_match(lua_Value s_val, lua_Value pat_val) {
    const char* s = lua_to_str(s_val);
    const char* pat = lua_to_str(pat_val);
    size_t slen = lua_str_byte_len(s_val);
    size_t ms = 0, me = 0;
    size_t cap_s[DUO_LP_MAXCAP], cap_e[DUO_LP_MAXCAP];
    int ncap = 0;
    if (!duo_lp_match_caps(s, slen, 0, pat, pat + strlen(pat), &ms, &me, cap_s, cap_e, &ncap)) return lua_val_nil();
    if (ncap > 0) {
        for (int i = 1; i < ncap; i++) {
            lua_mret_push(lua_val_from_str_len(s + cap_s[i], cap_e[i] - cap_s[i]));
        }
        return lua_val_from_str_len(s + cap_s[0], cap_e[0] - cap_s[0]);
    }
    return lua_val_from_str_len(s + ms, me - ms);
}

static size_t duo_repl_expand(const char* repl, size_t rlen, char* out,
                              const char* s,
                              const size_t* cap_s, const size_t* cap_e, int ncap) {
    size_t n = 0;
    for (size_t i = 0; i < rlen; i++) {
        char c = repl[i];
        if (c == '%' && i + 1 < rlen) {
            char d = repl[i + 1];
            if (d == '%') { out[n++] = '%'; i++; continue; }
            if (d >= '1' && d <= '9') {
                int idx = d - '1';
                if (idx < ncap) {
                    size_t cs = cap_s[idx], ce = cap_e[idx];
                    memcpy(out + n, s + cs, ce - cs);
                    n += ce - cs;
                }
                i++;
                continue;
            }
        }
        out[n++] = c;
    }
    return n;
}

static inline lua_Value lua_str_gsub(lua_Value s_val, lua_Value pat_val, lua_Value repl_val) {
    const char* s = lua_to_str(s_val);
    const char* pat = lua_to_str(pat_val);
    const char* repl = lua_to_str(repl_val);
    size_t slen = lua_str_byte_len(s_val);
    size_t rlen = lua_str_byte_len(repl_val);
    size_t pos = 0;
    char* buf = NULL;
    size_t len = 0, cap = 0;
    int count = 0;
    char* erbuf = malloc(rlen + slen + 1);
    if (!erbuf) erbuf = NULL;
    while (1) {
        size_t ms = 0, me = 0;
        size_t cap_s[DUO_LP_MAXCAP], cap_e[DUO_LP_MAXCAP];
        int ncap = 0;
        if (!duo_lp_match_caps(s, slen, pos, pat, pat + strlen(pat), &ms, &me, cap_s, cap_e, &ncap)) break;
        size_t elen = erbuf ? duo_repl_expand(repl, rlen, erbuf, s, cap_s, cap_e, ncap) : rlen;
        const char* erepl = erbuf ? erbuf : repl;
        if (len + (ms - pos) + elen > cap) {
            size_t nc = cap ? cap : 64;
            while (len + (ms - pos) + elen > nc) nc *= 2;
            buf = realloc(buf, nc);
            cap = nc;
        }
        memcpy(buf + len, s + pos, ms - pos);
        len += ms - pos;
        memcpy(buf + len, erepl, elen);
        len += elen;
        count++;
        pos = me;
        if (me == ms && pos < slen) pos++;
        if (pos > slen) break;
    }
    if (erbuf) free(erbuf);
    if (count == 0) return s_val;
    if (len + (slen - pos) + 1 > cap) {
        buf = realloc(buf, len + (slen - pos) + 1);
    }
    memcpy(buf + len, s + pos, slen - pos);
    len += slen - pos;
    buf[len] = 0;
    lua_mret_clear();
    lua_Value out = lua_val_from_str_len(buf, len);
    free(buf);
    lua_mret_push(out);
    lua_mret_push(lua_val_from_num((double)count));
    return lua_mret_get(0);
}

/* One cursor PER gmatch. There used to be a single file-static
 * GmatchState shared by the whole program, so a gmatch opened inside
 * another gmatch's loop body overwrote the outer cursor: the inner
 * iterator ran to exhaustion and set active = 0, the outer loop then read
 * that same flag on its next step and stopped. Three lines x four words
 * came out as four words total, with no diagnostic (gap[035]).
 *
 * The cursor rides inside the iterator VALUE, so iterator identity IS
 * cursor identity and nesting depth is unbounded. The value is a closure
 * with a reserved id — the prefix here is layout-compatible with
 * lua_Closure (header, id, nup) exactly as the generated duo_closure_N
 * structs are — and lua_invoke, the single dispatch point for both
 * VAL_FUNC and VAL_CLOSURE, recognises that id and steps the cursor. */
typedef struct {
    char* s;
    char* pat;
    size_t slen;
    size_t pos;
    int active;
} GmatchState;

typedef struct {
    duo_ObjHeader header;
    int id;
    int nup;
    GmatchState st;
} DuoGmatchIter;

/* The source and pattern copies are released the moment the iteration
 * ends, which is the common path; the iterator object itself stays alive
 * because Lua lets an exhausted iterator be called again and answer nil. */
static void duo_gmatch_finish(GmatchState* g) {
    g->active = 0;
    if (g->s) { free(g->s); g->s = NULL; }
    if (g->pat) { free(g->pat); g->pat = NULL; }
}

static lua_Value duo_gmatch_step(lua_Closure* cl) {
    GmatchState* g = &((DuoGmatchIter*)(void*)cl)->st;
    if (!g->active || !g->s || !g->pat) return lua_val_nil();
    size_t slen = g->slen;
    if (g->pos > slen) { duo_gmatch_finish(g); return lua_val_nil(); }
    size_t ms = 0, me = 0;
    if (!duo_lp_find_at(g->s, slen, g->pat, g->pos, &ms, &me)) {
        duo_gmatch_finish(g);
        return lua_val_nil();
    }
    size_t mlen = me - ms;
    g->pos = me;
    if (me == ms && g->pos < slen) g->pos++;
    return lua_val_from_str_len(g->s + ms, mlen);
}

static inline lua_Value lua_str_gmatch(lua_Value s_val, lua_Value pat_val, lua_Value init_val) {
    (void)init_val;
    DuoGmatchIter* it = (DuoGmatchIter*)calloc(1, sizeof(DuoGmatchIter));
    if (!it) return lua_val_nil();
    it->header.refcount = 1;
    it->header.flags = 0;
    it->header.type_tag = VAL_CLOSURE;
    it->id = DUO_GMATCH_CLOSURE_ID;
    it->nup = 0;
    GmatchState* g = &it->st;
    g->slen = lua_str_byte_len(s_val);
    g->s = malloc(g->slen + 1);
    memcpy(g->s, lua_to_str(s_val), g->slen);
    g->s[g->slen] = '\0';
    g->pat = strdup(lua_to_str(pat_val));
    g->pos = 0;
    g->active = 1;
    return lua_val_from_closure((lua_Closure*)(void*)it);
}

static inline lua_Value lua_str_dump(lua_Value f_val, lua_Value strip_val) {
    (void)f_val; (void)strip_val;
    return lua_val_from_literal("function", 3369875416u, 8);
}

static inline lua_Value lua_str_split(lua_Value s_val, lua_Value sep_val) {
    const char* str = lua_to_str(s_val);
    const char* sep = lua_to_str(sep_val);
    size_t slen = lua_str_byte_len(s_val);
    size_t seplen = lua_str_byte_len(sep_val);
    lua_Value tbl = lua_table_new();
    int idx = 1;
    const char* start = str;
    const char* end = str + slen;
    if (seplen == 0) {
        for (size_t i = 0; i < slen; i++) {
            lua_table_set_i64(tbl, idx++, lua_val_from_str_len(str + i, 1));
        }
    } else {
        while (start <= end) {
            const char* found = NULL;
            for (const char* p = start; p + seplen <= end; p++) {
                if (memcmp(p, sep, seplen) == 0) { found = p; break; }
            }
            if (found) {
                lua_table_set_i64(tbl, idx++, lua_val_from_str_len(start, found - start));
                start = found + seplen;
            } else {
                lua_table_set_i64(tbl, idx++, lua_val_from_str_len(start, end - start));
                break;
            }
        }
    }
    return tbl;
}

static inline lua_Value lua_str_starts_with(lua_Value s_val, lua_Value prefix_val) {
    const char* str = lua_to_str(s_val);
    const char* prefix = lua_to_str(prefix_val);
    size_t slen = lua_str_byte_len(s_val);
    size_t plen = lua_str_byte_len(prefix_val);
    if (plen > slen) return lua_val_from_bool(0);
    return lua_val_from_bool(memcmp(str, prefix, plen) == 0);
}

static inline lua_Value lua_str_ends_with(lua_Value s_val, lua_Value suffix_val) {
    const char* str = lua_to_str(s_val);
    const char* suffix = lua_to_str(suffix_val);
    size_t slen = lua_str_byte_len(s_val);
    size_t suflen = lua_str_byte_len(suffix_val);
    if (suflen > slen) return lua_val_from_bool(0);
    return lua_val_from_bool(memcmp(str + slen - suflen, suffix, suflen) == 0);
}

// ═══════════════════════════════════════════════════════════════
// Arena allocator — O(1) bump allocation, O(1) reset, zero fragmentation
// This is the #1 technique for making ward's WASM memory faster than malloc
// ═══════════════════════════════════════════════════════════════
typedef struct { uint8_t* base; size_t cap; size_t pos; } DuoArena;

static inline DuoArena* duo_arena_new(size_t cap) {
    DuoArena* a = (DuoArena*)malloc(sizeof(DuoArena));
    a->base = (uint8_t*)malloc(cap);
    a->cap = cap;
    a->pos = 0;
    return a;
}

static inline void* duo_arena_alloc(DuoArena* a, size_t size) {
    size = (size + 7) & ~7; // 8-byte align
    if (__builtin_expect(a->pos + size <= a->cap, 1)) {
        void* ptr = a->base + a->pos;
        a->pos += size;
        return ptr;
    }
    // Grow: double capacity
    while (a->pos + size > a->cap) a->cap *= 2;
    a->base = (uint8_t*)realloc(a->base, a->cap);
    void* ptr = a->base + a->pos;
    a->pos += size;
    return ptr;
}

static inline void duo_arena_reset(DuoArena* a) { a->pos = 0; }

static inline void duo_arena_free(DuoArena* a) {
    free(a->base); free(a);
}

// ═══════════════════════════════════════════════════════════════
// Pool allocator — fixed-size object pool with freelist (O(1) get/put)
// Ward uses this for WASM stack frames, call frames, isolates
// ═══════════════════════════════════════════════════════════════
typedef struct DuoPoolSlot { struct DuoPoolSlot* next; } DuoPoolSlot;
typedef struct { uint8_t* base; size_t obj_size; size_t cap; DuoPoolSlot* free_list; } DuoPool;

static inline DuoPool* duo_pool_new(size_t obj_size, size_t count) {
    if (obj_size < sizeof(DuoPoolSlot)) obj_size = sizeof(DuoPoolSlot);
    DuoPool* p = (DuoPool*)malloc(sizeof(DuoPool));
    p->obj_size = obj_size;
    p->cap = count;
    p->base = (uint8_t*)malloc(obj_size * count);
    p->free_list = NULL;
    for (size_t i = 0; i < count; i++) {
        DuoPoolSlot* s = (DuoPoolSlot*)(p->base + i * obj_size);
        s->next = p->free_list;
        p->free_list = s;
    }
    return p;
}

static inline void* duo_pool_get(DuoPool* p) {
    if (__builtin_expect(p->free_list != NULL, 1)) {
        void* obj = p->free_list;
        p->free_list = p->free_list->next;
        return obj;
    }
    return malloc(p->obj_size); // fallback
}

static inline void duo_pool_put(DuoPool* p, void* obj) {
    DuoPoolSlot* s = (DuoPoolSlot*)obj;
    s->next = p->free_list;
    p->free_list = s;
}

// ═══════════════════════════════════════════════════════════════
// Computed goto dispatch — THE technique for fast interpreters
// GCC/Clang extension: &&label gives the address of a label
// Eliminates branch predictor pollution from a central switch
// ═══════════════════════════════════════════════════════════════
#define DUO_DISPATCH_TABLE(name, ...) \
    static const void* name[] = { __VA_ARGS__ }
#define DUO_DISPATCH(table, op) goto *table[op]
#define DUO_LABEL(name) name:
#define DUO_NEXT(table, pc, code) goto *table[code[pc++]]

// ═══════════════════════════════════════════════════════════════
// SIMD helpers — portable vector intrinsics via Clang extensions
// These compile to NEON on ARM, AVX2 on x86, WASM SIMD on wasm
// ═══════════════════════════════════════════════════════════════
#ifndef DUO_SIMD_TYPES_DEFINED
#define DUO_SIMD_TYPES_DEFINED
typedef float duo_v4f32 __attribute__((vector_size(16)));
typedef float duo_v8f32 __attribute__((vector_size(32)));
typedef double duo_v2f64 __attribute__((vector_size(16)));
typedef double duo_v4f64 __attribute__((vector_size(32)));
typedef int32_t duo_v4i32 __attribute__((vector_size(16)));
typedef int32_t duo_v8i32 __attribute__((vector_size(32)));
typedef int64_t duo_v4i64 __attribute__((vector_size(32)));
#endif

static inline duo_v8f32 duo_v8f32_load(const float* p) { duo_v8f32 v; memcpy(&v, p, 32); return v; }
static inline duo_v4f64 duo_v4f64_load(const double* p) { duo_v4f64 v; memcpy(&v, p, 32); return v; }
static inline void duo_v8f32_store(float* p, duo_v8f32 v) { memcpy(p, &v, 32); }
static inline void duo_v4f64_store(double* p, duo_v4f64 v) { memcpy(p, &v, 32); }

static inline float duo_v8f32_sum(duo_v8f32 v) { return v[0]+v[1]+v[2]+v[3]+v[4]+v[5]+v[6]+v[7]; }
static inline double duo_v4f64_sum(duo_v4f64 v) { return v[0]+v[1]+v[2]+v[3]; }

static inline duo_v4f64 duo_v4f64_splat(double x) { return (duo_v4f64){x,x,x,x}; }

// Fused multiply-add: a*b+c in one instruction (FMA3/NEON FMLA)
static inline duo_v8f32 duo_v8f32_fma(duo_v8f32 a, duo_v8f32 b, duo_v8f32 c) { return a * b + c; }
static inline duo_v4f64 duo_v4f64_fma(duo_v4f64 a, duo_v4f64 b, duo_v4f64 c) { return a * b + c; }

// Dot product via SIMD reduction
static inline float duo_simd_dot_f32(const float* a, const float* b, size_t n) {
    duo_v8f32 acc = {0};
    size_t i = 0;
    for (; i + 8 <= n; i += 8) {
        duo_v8f32 va = duo_v8f32_load(a + i);
        duo_v8f32 vb = duo_v8f32_load(b + i);
        acc = duo_v8f32_fma(va, vb, acc);
    }
    float sum = duo_v8f32_sum(acc);
    for (; i < n; i++) sum += a[i] * b[i];
    return sum;
}

static inline double duo_simd_dot_f64(const double* a, const double* b, size_t n) {
    duo_v4f64 acc = {0};
    size_t i = 0;
    for (; i + 4 <= n; i += 4) {
        duo_v4f64 va = duo_v4f64_load(a + i);
        duo_v4f64 vb = duo_v4f64_load(b + i);
        acc = duo_v4f64_fma(va, vb, acc);
    }
    double sum = duo_v4f64_sum(acc);
    for (; i < n; i++) sum += a[i] * b[i];
    return sum;
}

// SIMD matmul kernel (vectorized inner loop, C += A*B)
static inline void duo_simd_matmul_f32(
    const float* restrict A, const float* restrict B, float* restrict C,
    size_t M, size_t N, size_t K) {
    for (size_t i = 0; i < M; i++) {
        for (size_t k = 0; k < K; k++) {
            const float a_ik = A[i * K + k];
            const float* restrict b_row = B + k * N;
            float* restrict c_row = C + i * N;
            size_t j = 0;
            const size_t j_end = N & ~((size_t)7);
            for (; j < j_end; j += 8) {
                duo_v8f32 acc = duo_v8f32_load(c_row + j);
                duo_v8f32 bv = duo_v8f32_load(b_row + j);
                duo_v8f32 av = (duo_v8f32){a_ik,a_ik,a_ik,a_ik,a_ik,a_ik,a_ik,a_ik};
                acc = duo_v8f32_fma(av, bv, acc);
                duo_v8f32_store(c_row + j, acc);
            }
            for (; j < N; j++) c_row[j] += a_ik * b_row[j];
        }
    }
}

static inline void duo_simd_matmul_f64(
    const double* restrict A, const double* restrict B, double* restrict C,
    size_t M, size_t N, size_t K) {
    for (size_t i = 0; i < M; i++) {
        for (size_t k = 0; k < K; k++) {
            const double a_ik = A[i * K + k];
            const double* restrict b_row = B + k * N;
            double* restrict c_row = C + i * N;
            size_t j = 0;
            const size_t j_end = N & ~((size_t)3);
            for (; j < j_end; j += 4) {
                duo_v4f64 acc = duo_v4f64_load(c_row + j);
                duo_v4f64 bv = duo_v4f64_load(b_row + j);
                acc = duo_v4f64_fma(duo_v4f64_splat(a_ik), bv, acc);
                duo_v4f64_store(c_row + j, acc);
            }
            for (; j < N; j++) c_row[j] += a_ik * b_row[j];
        }
    }
}

// Zero-copy string view (pointer + length, no allocation)
typedef struct { const char* ptr; size_t len; } DuoStrView;

static inline DuoStrView duo_str_view(const char* s, size_t len) {
    return (DuoStrView){s, len};
}
static inline DuoStrView duo_str_view_slice(DuoStrView sv, size_t start, size_t end) {
    if (start > sv.len) start = sv.len;
    if (end > sv.len) end = sv.len;
    return (DuoStrView){sv.ptr + start, end - start};
}
static inline int duo_str_view_eq(DuoStrView a, DuoStrView b) {
    return a.len == b.len && memcmp(a.ptr, b.ptr, a.len) == 0;
}
static inline uint8_t duo_str_view_byte(DuoStrView sv, size_t idx) {
    return (idx < sv.len) ? (uint8_t)sv.ptr[idx] : 0;
}

static int duo_pack_option(const char** fmt, char* opt_out) {
    const char* f = *fmt;
    while (*f == '<' || *f == '>' || *f == '=' || *f == '!') f++;
    int count = 0;
    while (*f >= '0' && *f <= '9') { count *= 10; count += (*f - '0'); f++; }
    char op = *f;
    if (!op) return 0;
    *fmt = f + 1;
    if (opt_out) *opt_out = op;
    switch (op) {
        case 'c': return count > 0 ? count : 1;
        case 'b': case 'B': return 1;
        case 'h': case 'H': return 2;
        case 'i': case 'I': return 4;
        case 'j': case 'J': return 8;
        case 'f': return 4;
        case 'd': case 'n': return 8;
        case 's': return (int)sizeof(size_t);
        default: return 0;
    }
}

static inline lua_Value lua_str_packsize(lua_Value fmt) {
    const char* f = lua_to_str(fmt);
    int total = 0;
    char op = 0;
    while (*f) {
        int sz = duo_pack_option(&f, &op);
        if (sz <= 0) break;
        total += sz;
    }
    return lua_val_from_num((double)total);
}

static void duo_pack_append(char** buf, size_t* len, size_t* cap, const void* data, size_t n) {
    if (*len + n > *cap) {
        size_t nc = *cap ? *cap : 64;
        while (*len + n > nc) nc *= 2;
        *buf = realloc(*buf, nc);
        *cap = nc;
    }
    memcpy(*buf + *len, data, n);
    *len += n;
}

static inline lua_Value lua_str_pack(lua_Value fmt, lua_Value v1, lua_Value v2) {
    const char* f = lua_to_str(fmt);
    char* buf = NULL;
    size_t len = 0, cap = 0;
    lua_Value vals[2] = { v1, v2 };
    int vi = 0;
    char op = 0;
    while (*f) {
        int sz = duo_pack_option(&f, &op);
        if (sz <= 0) break;
        if (op == 'c') {
            const char* s = lua_to_str(vals[vi < 2 ? vi : 1]);
            duo_pack_append(&buf, &len, &cap, s, (size_t)sz);
            if (vi < 2) vi++;
            continue;
        }
        lua_Value v = vals[vi < 2 ? vi : 1];
        if (vi < 2) vi++;
        if (op == 's') {
            const char* s = lua_to_str(v);
            size_t slen = strlen(s);
            duo_pack_append(&buf, &len, &cap, &slen, sizeof(size_t));
            duo_pack_append(&buf, &len, &cap, s, slen);
            continue;
        }
        if (op == 'b') { int8_t x = (int8_t)lua_to_num(v); duo_pack_append(&buf, &len, &cap, &x, 1); }
        else if (op == 'B') { uint8_t x = (uint8_t)lua_to_num(v); duo_pack_append(&buf, &len, &cap, &x, 1); }
        else if (op == 'h') { int16_t x = (int16_t)lua_to_num(v); duo_pack_append(&buf, &len, &cap, &x, 2); }
        else if (op == 'H') { uint16_t x = (uint16_t)lua_to_num(v); duo_pack_append(&buf, &len, &cap, &x, 2); }
        else if (op == 'i') { int32_t x = (int32_t)lua_to_num(v); duo_pack_append(&buf, &len, &cap, &x, 4); }
        else if (op == 'I') { uint32_t x = (uint32_t)lua_to_num(v); duo_pack_append(&buf, &len, &cap, &x, 4); }
        else if (op == 'j') { int64_t x = (int64_t)lua_to_num(v); duo_pack_append(&buf, &len, &cap, &x, 8); }
        else if (op == 'J') { uint64_t x = (uint64_t)lua_to_num(v); duo_pack_append(&buf, &len, &cap, &x, 8); }
        else if (op == 'f') { float x = (float)lua_to_num(v); duo_pack_append(&buf, &len, &cap, &x, 4); }
        else { double x = lua_to_num(v); duo_pack_append(&buf, &len, &cap, &x, 8); }
    }
    if (!buf) return lua_val_lit("");
    lua_Value out = lua_val_from_str_len(buf, len);
    free(buf);
    return out;
}

static inline lua_Value lua_str_unpack(lua_Value fmt, lua_Value s, lua_Value pos) {
    const char* f = lua_to_str(fmt);
    const char* str = lua_to_str(s);
    size_t slen = lua_str_byte_len(s);
    size_t idx = pos.type == VAL_NIL ? 0 : (size_t)lua_to_num(pos) - 1;
    if (idx >= slen) return lua_val_nil();
    char op = 0;
    int sz = duo_pack_option(&f, &op);
    if (sz <= 0 || idx + (size_t)sz > slen) return lua_val_nil();
    const unsigned char* p = (const unsigned char*)(str + idx);
    if (op == 'b') return lua_val_from_num((double)(int8_t)p[0]);
    if (op == 'B') return lua_val_from_num((double)p[0]);
    if (op == 'h') { int16_t x; memcpy(&x, p, 2); return lua_val_from_num((double)x); }
    if (op == 'H') { uint16_t x; memcpy(&x, p, 2); return lua_val_from_num((double)x); }
    if (op == 'i') { int32_t x; memcpy(&x, p, 4); return lua_val_from_num((double)x); }
    if (op == 'I') { uint32_t x; memcpy(&x, p, 4); return lua_val_from_num((double)x); }
    if (op == 'j') { int64_t x; memcpy(&x, p, 8); return lua_val_from_num((double)x); }
    if (op == 'J') { uint64_t x; memcpy(&x, p, 8); return lua_val_from_num((double)x); }
    if (op == 'f') { float x; memcpy(&x, p, 4); return lua_val_from_num((double)x); }
    if (op == 'd' || op == 'n') { double x; memcpy(&x, p, 8); return lua_val_from_num(x); }
    if (op == 'c') return lua_val_from_str_len(str + idx, (size_t)sz);
    return lua_val_nil();
}

static inline lua_Value lua_utf8_char(lua_Value c) {
    int n = (int)lua_to_num(c);
    char buf[5] = {0};
    size_t len = 1;
    if (n < 0x80) buf[0] = n;
    else if (n < 0x800) { buf[0] = 0xC0 | (n >> 6); buf[1] = 0x80 | (n & 0x3F); len = 2; }
    else if (n < 0x10000) { buf[0] = 0xE0 | (n >> 12); buf[1] = 0x80 | ((n >> 6) & 0x3F); buf[2] = 0x80 | (n & 0x3F); len = 3; }
    else { buf[0] = 0xF0 | (n >> 18); buf[1] = 0x80 | ((n >> 12) & 0x3F); buf[2] = 0x80 | ((n >> 6) & 0x3F); buf[3] = 0x80 | (n & 0x3F); len = 4; }
    return lua_val_from_str_len(buf, len);
}

static inline lua_Value lua_utf8_offset(lua_Value s_val, lua_Value n_val, lua_Value i_val) {
    const char* s = lua_to_str(s_val);
    int n = (int)lua_to_num(n_val);
    int len = (int)strlen(s);
    int i = i_val.type == VAL_NIL ? (n >= 0 ? 1 : len + 1) : (int)lua_to_num(i_val);
    if (i < 1 || i > len + 1) return lua_val_nil();
    int byte_pos = i - 1;
    if (n == 0) {
        while (byte_pos > 0 && (s[byte_pos] & 0xC0) == 0x80) byte_pos--;
        lua_mret_clear();
        int char_pos = 1;
        for (int j = 0; j < byte_pos; j++) {
            if ((s[j] & 0xC0) != 0x80) char_pos++;
        }
        lua_mret_push(lua_val_from_num((double)char_pos));
        return lua_val_from_num((double)(byte_pos + 1));
    }
    if (n > 0) {
        n--;
        while (n > 0 && byte_pos < len) {
            byte_pos++;
            if ((s[byte_pos] & 0xC0) != 0x80) n--;
        }
    } else {
        while (n < 0 && byte_pos > 0) {
            byte_pos--;
            if ((s[byte_pos] & 0xC0) != 0x80) n++;
        }
    }
    if (n == 0 && byte_pos <= len) {
        lua_mret_clear();
        int char_pos = 1;
        for (int j = 0; j < byte_pos; j++) {
            if ((s[j] & 0xC0) != 0x80) char_pos++;
        }
        lua_mret_push(lua_val_from_num((double)char_pos));
        return lua_val_from_num((double)(byte_pos + 1));
    }
    return lua_val_nil();
}

static inline lua_Value lua_tbl_pack(lua_Value v) {
    lua_Value t = lua_table_new_with_capacity(1, 1);
    lua_table_init_lit(t, "n", lua_val_from_num(1.0));
    lua_table_set_raw_i64(t, 1, v);
    return t;
}

static inline lua_Value lua_tbl_pack_argv(int n, lua_Value* argv) {
    lua_Value t = lua_table_new_with_capacity(n, 1);
    lua_table_init_lit(t, "n", lua_val_from_num((double)n));
    for (int i = 0; i < n; i++) {
        lua_table_set_raw_i64(t, i + 1, argv[i]);
    }
    return t;
}

static inline lua_Value lua_tbl_pack_argv_fn(int argc, lua_Value* argv) {
    return lua_tbl_pack_argv(argc, argv);
}

static inline lua_Value lua_tbl_freeze(lua_Value table) {
    if (table.type != VAL_TABLE) return table;
    lua_Table* t = (lua_Table*)table.as.tval;
    if (t) t->frozen = true;
    return table;
}

static inline lua_Value lua_tbl_isfrozen(lua_Value table) {
    if (table.type != VAL_TABLE) return lua_val_from_bool(false);
    lua_Table* t = (lua_Table*)table.as.tval;
    return lua_val_from_bool(t && t->frozen);
}

static lua_Value lua_co_wrap_thread = { .type = VAL_NIL };
static lua_Value lua_co_wrap_fn(lua_Value arg) {
    return lua_co_resume(lua_co_wrap_thread, arg);
}

static inline lua_Value lua_co_wrap(lua_Value f) {
    lua_co_wrap_thread = lua_co_create(f);
    return lua_val_from_func(lua_co_wrap_fn);
}

static inline lua_Value lua_co_isyieldable(void) {
    return lua_val_from_bool(active_thread != NULL);
}

